-- Get The Penelopiad project ID
SET @penelopiad_id = (SELECT id FROM projects WHERE title = 'The Penelopiad' LIMIT 1);

-- Add tags for The Penelopiad
INSERT INTO projectTags (projectId, tagId)
SELECT @penelopiad_id, id FROM tags WHERE name IN ('Greek Mythology', '2020', 'University Theatre', 'Feminist Theatre', 'Margaret Atwood', 'Contemporary Adaptation')
ON DUPLICATE KEY UPDATE projectId = projectId;

